// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type TrolleyProblemProps = Record<string, any>;

const TrolleyProblem: React.FC<TrolleyProblemProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = true,
  durationInSeconds = 10,
  trackColor = "#64748b",
  trolleyColor = "#ef4444",
  personColor = "#f8fafc",
  leverColor = "#f59e0b",
  textColor = "#ffffff",
  upperTrackCount = 1,
  lowerTrackCount = 5,
}) => {
  useFontLoader(["Outfit"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Safety logic for transparent backgrounds
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Key Coordinates
  const cx = width / 2;
  const cy = height / 2;
  const mainTrackEndX = width * 0.4;
  const splitEndX = width * 0.55;
  const upperTrackY = cy - height * 0.25;
  const lowerTrackY = cy + height * 0.25;

  const trackStrokeWidth = height * 0.015;
  const trolleyWidth = width * 0.12;
  const trolleyHeight = height * 0.12;
  const personSize = height * 0.04;

  // Track Paths
  const pathUpper = `M 0 ${cy} L ${mainTrackEndX} ${cy} L ${splitEndX} ${upperTrackY} L ${width} ${upperTrackY}`;
  const pathLower = `M ${mainTrackEndX} ${cy} L ${splitEndX} ${lowerTrackY} L ${width} ${lowerTrackY}`;

  // Track drawing animation
  const maxPathLength = width * 1.5;
  const drawOffset = interpolate(frame, [15, 60], [maxPathLength, 0], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  const leverScale = spring({
    frame: frame - 60,
    fps,
    config: { damping: 12 },
  });

  const trolleyTargetX = mainTrackEndX - trolleyWidth * 0.8;
  const trolleyX = interpolate(
    frame,
    [70, fps * durationInSeconds - 30],
    [-trolleyWidth * 2, trolleyTargetX],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
      easing: Easing.out(Easing.quad),
    }
  );

  // Lever urgency wobble
  const trolleyProgress = interpolate(
    frame,
    [70, fps * durationInSeconds - 30],
    [0, 1],
    { extrapolateRight: "clamp" }
  );
  const leverWobble =
    trolleyProgress > 0.6 && trolleyProgress < 0.98
      ? Math.sin(frame * 0.8) * 10
      : 0;

  // Helper to render people on a track
  const renderPeople = (
    count: number,
    trackY: number,
    delayFrame: number,
    label: string,
    actionText: string
  ) => {
    return (
      <g style={{ transition: "none" }}>
        {/* Track Label */}
        <text
          x={splitEndX + width * 0.15}
          y={trackY - height * 0.08}
          fill={textColor}
          fontSize={height * 0.03}
          fontFamily="Outfit"
          fontWeight="600"
          textAnchor="middle"
          opacity={interpolate(frame, [delayFrame, delayFrame + 20], [0, 0.7], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })}
          style={{ transition: "none" }}
        >
          {label}
        </text>
        <text
          x={splitEndX + width * 0.15}
          y={trackY - height * 0.12}
          fill={leverColor}
          fontSize={height * 0.025}
          fontFamily="Outfit"
          fontWeight="800"
          textAnchor="middle"
          letterSpacing={2}
          opacity={interpolate(frame, [delayFrame, delayFrame + 20], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          })}
          style={{ transition: "none", textTransform: "uppercase" }}
        >
          {actionText}
        </text>

        {Array.from({ length: count }).map((_, i) => {
          const progress = count === 1 ? 0.5 : i / (count - 1);
          // Spread people along the straight part of the branched track
          const spreadWidth = width * 0.25;
          const x = splitEndX + width * 0.05 + progress * spreadWidth;
          const pScale = spring({
            frame: frame - (delayFrame + i * 4),
            fps,
            config: { damping: 14 },
          });

          return (
            <g
              key={i}
              transform={`translate(${x}, ${trackY}) scale(${pScale})`}
              style={{ transition: "none" }}
            >
              <circle
                cx={0}
                cy={-personSize * 1.5}
                r={personSize * 0.4}
                fill={personColor}
                style={{ transition: "none" }}
              />
              <rect
                x={-personSize * 0.4}
                y={-personSize * 0.9}
                width={personSize * 0.8}
                height={personSize * 1.2}
                rx={personSize * 0.2}
                fill={personColor}
                style={{ transition: "none" }}
              />
            </g>
          );
        })}
      </g>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Outfit",
        transition: "none",
      }}
    >
      <svg
        width={width}
        height={height}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          transition: "none",
        }}
      >
        {/* Ties (Wooden Planks) */}
        <g opacity={0.3} style={{ transition: "none" }}>
          <path
            d={pathUpper}
            stroke={trackColor}
            strokeWidth={trackStrokeWidth * 4}
            strokeDasharray={`${width * 0.01} ${width * 0.03}`}
            strokeDashoffset={drawOffset}
            fill="none"
            strokeLinecap="butt"
            style={{ transition: "none" }}
          />
          <path
            d={pathLower}
            stroke={trackColor}
            strokeWidth={trackStrokeWidth * 4}
            strokeDasharray={`${width * 0.01} ${width * 0.03}`}
            strokeDashoffset={drawOffset}
            fill="none"
            strokeLinecap="butt"
            style={{ transition: "none" }}
          />
        </g>

        {/* Metal Rails */}
        <path
          d={pathUpper}
          stroke={trackColor}
          strokeWidth={trackStrokeWidth}
          strokeDasharray={maxPathLength}
          strokeDashoffset={drawOffset}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        />
        <path
          d={pathLower}
          stroke={trackColor}
          strokeWidth={trackStrokeWidth}
          strokeDasharray={maxPathLength}
          strokeDashoffset={drawOffset}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{ transition: "none" }}
        />

        {/* People on Tracks */}
        {renderPeople(upperTrackCount, upperTrackY, 45, `${upperTrackCount} Person`, "PULL LEVER")}
        {renderPeople(lowerTrackCount, lowerTrackY, 55, `${lowerTrackCount} People`, "DO NOTHING")}

        {/* The Lever */}
        <g
          transform={`translate(${mainTrackEndX}, ${
            cy + height * 0.15
          }) scale(${leverScale})`}
          style={{ transition: "none" }}
        >
          {/* Base */}
          <rect
            x={-width * 0.02}
            y={0}
            width={width * 0.04}
            height={height * 0.04}
            rx={height * 0.01}
            fill={trackColor}
            style={{ transition: "none" }}
          />
          {/* Handle */}
          <g
            transform={`rotate(${leverWobble} 0 0)`}
            style={{ transition: "none" }}
          >
            <line
              x1={0}
              y1={height * 0.02}
              x2={-width * 0.02}
              y2={-height * 0.06}
              stroke={leverColor}
              strokeWidth={height * 0.015}
              strokeLinecap="round"
              style={{ transition: "none" }}
            />
            <circle
              cx={-width * 0.02}
              cy={-height * 0.06}
              r={height * 0.02}
              fill={leverColor}
              style={{ transition: "none" }}
            />
          </g>
        </g>

        {/* The Trolley */}
        <g
          transform={`translate(${trolleyX}, ${cy - trolleyHeight})`}
          style={{ transition: "none" }}
        >
          {/* Trolley Body */}
          <rect
            x={0}
            y={0}
            width={trolleyWidth}
            height={trolleyHeight}
            rx={height * 0.02}
            fill={trolleyColor}
            style={{ transition: "none" }}
          />
          {/* Windows */}
          <rect
            x={trolleyWidth * 0.6}
            y={trolleyHeight * 0.2}
            width={trolleyWidth * 0.3}
            height={trolleyHeight * 0.4}
            rx={height * 0.01}
            fill={backgroundColor}
            opacity={0.8}
            style={{ transition: "none" }}
          />
          <rect
            x={trolleyWidth * 0.1}
            y={trolleyHeight * 0.2}
            width={trolleyWidth * 0.4}
            height={trolleyHeight * 0.4}
            rx={height * 0.01}
            fill={backgroundColor}
            opacity={0.8}
            style={{ transition: "none" }}
          />

          {/* Wheels */}
          {[trolleyWidth * 0.2, trolleyWidth * 0.8].map((wheelX, idx) => (
            <circle
              key={idx}
              cx={wheelX}
              cy={trolleyHeight}
              r={height * 0.025}
              fill="#1e293b"
              stroke={trackColor}
              strokeWidth={height * 0.005}
              style={{ transition: "none" }}
            />
          ))}
          {/* Wheel Spokes (Spinning) */}
          {[trolleyWidth * 0.2, trolleyWidth * 0.8].map((wheelX, idx) => (
            <g
              key={`spoke-${idx}`}
              transform={`translate(${wheelX}, ${trolleyHeight}) rotate(${
                trolleyX * 2
              })`}
              style={{ transition: "none" }}
            >
              <line
                x1={-height * 0.015}
                y1={0}
                x2={height * 0.015}
                y2={0}
                stroke={trackColor}
                strokeWidth={height * 0.005}
                style={{ transition: "none" }}
              />
              <line
                x1={0}
                y1={-height * 0.015}
                x2={0}
                y2={height * 0.015}
                stroke={trackColor}
                strokeWidth={height * 0.005}
                style={{ transition: "none" }}
              />
            </g>
          ))}
        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default TrolleyProblem;